import pytest

DEFAULTS: dict[str, str] = {"mode": "fast", "level": "3"}


def settings(keys: list[str], values: list[str]) -> list[str]:
    """Overlay keys[i] -> values[i] on DEFAULTS and return the resulting values.

    Output order: mode, then level, then any other keys in the order given.
    """
    merged: dict[str, str] = dict(DEFAULTS)
    for k, v in zip(keys, values, strict=True):
        merged[k] = v
    extras = [k for k in dict.fromkeys(keys) if k not in DEFAULTS]
    order = ["mode", "level", *extras]
    return [merged[k] for k in order]


def test_no_overrides() -> None:
    assert settings([], []) == ["fast", "3"]


def test_override_mode_only() -> None:
    assert settings(["mode"], ["slow"]) == ["slow", "3"]


def test_override_defaults_reordered() -> None:
    assert settings(["level", "mode"], ["5", "eco"]) == ["eco", "5"]


def test_extra_key_appended() -> None:
    assert settings(["color"], ["red"]) == ["fast", "3", "red"]


def test_mixed_extra_keys_keep_given_order() -> None:
    assert settings(["level", "color", "size"], ["7", "red", "L"]) == [
        "fast",
        "7",
        "red",
        "L",
    ]
